// npm run build && node --import tsx tests/browser/mapping/browser-diff-tree-panel-check.mjs
import assert from 'node:assert/strict';
import { spawn, execFileSync } from 'node:child_process';
import { mkdtemp, mkdir, writeFile, rm } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { DiagramStore } from '../../../infrastructure/core/persistence/store.ts';
import { DiagramChangeSessionStore } from '../../../infrastructure/mapping/changes/diagramChangeSessionStore.ts';
import { ChangeSessionService } from '../../../application/mapping/changes/changeSessionService.ts';
import { canvasSaveFixture } from '../../support/mappingDiagram.ts';
import { singleDiagramScene } from '../../../domain/core/diagrams/projectDiagramCanvas.ts';
import { diagramContentNodes } from '../../../domain/core/diagrams/diagramContentNodes.ts';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'diff-tree-browser-'));
let server;
const git = (...args) => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8' }).trim();
const commit = name => { git('add', '.'); git('-c', 'user.name=Fixture', '-c', 'user.email=fixture@example.test', 'commit', '-qm', name); return git('rev-parse', 'HEAD'); };
try {
  await seedMappingFixture(root, { ascii: 'Canvas A\n`-- Original', nodes: [] });
  await writeFile(path.join(root, '.gitignore'), '.diagrams/\n');
  const original = Array.from({ length: 30 }, (_, i) => `const value${i + 1} = ${i + 1};`);
  await writeFile(path.join(root, 'logic.ts'), original.join('\n') + '\n');
  await writeFile(path.join(root, 'removed.txt'), '<captured before>\n' + 'Removed application notes\n'.repeat(80).trimEnd());
  commit('Baseline');
  original[1] = 'const value2 = "captured after";'; original[26] = `const value27 = "${'long content '.repeat(30)}";`;
  await writeFile(path.join(root, 'logic.ts'), original.join('\n') + '\n');
  await rm(path.join(root, 'removed.txt')); await writeFile(path.join(root, 'binary.dat'), Buffer.from([0, 1, 0, 2]));
  await mkdir(path.join(root, 'extra'));
  for (let i = 0; i < 101; i++) await writeFile(path.join(root, 'extra', `${i}.txt`), `Added file ${i}\n`);
  const head = commit('Captured changes');
  const store = new DiagramStore(root), project = await store.loadProject(), repositoryId = project.repositories[0].id;
  await store.projectCatalogs.loadRepresentationCatalog(project.id);
  await store.projectCatalogs.saveMappingDiagram(project.id, { ...canvasSaveFixture({ name: 'Canvas B', scene: singleDiagramScene('Canvas B\n`-- Original') }), repositoryId });
  const changes = new ChangeSessionService(new DiagramChangeSessionStore(store.storeRoot), store, { list: () => [] });
  const discovered = await changes.discoverHunks({ repositoryId, commits: [head], offset: 0, limit: 200, includePatches: true });
  const mapping = (name, line, file) => ({ id: name, source: { line }, targets: discovered.hunks.filter(h => h.path === file).map(h => ({ kind: 'diff-hunk', hunkId: h.id })) });
  const tree = { ascii: 'Review\n|-- Logic\n|   `-- Detail\n|-- Removed file\n`-- Unmapped', mappings: [mapping('logic', 2, 'logic.ts'), mapping('removed', 4, 'removed.txt')] };
  const proposal = await changes.create({ title: 'Captured review', repositoryId, commits: [head], diffTree: tree, requestId: 'create' });
  const emptyProposal = await changes.create({ title: 'Empty review', repositoryId, commits: [], requestId: 'empty' });
  const id = proposal.changeSessionId, docA = proposal.documents.find(d => d.name !== 'Canvas B').documentId, docB = proposal.documents.find(d => d.name === 'Canvas B').documentId;
  await changes.apply(id, docA, 0, [{ method: 'patchDiagram', nodeId: 'grid:overview', start: 1, end: 1, patch: 'Canvas A updated' }], 'edit');
  const versioned = await changes.get(id);
  const jumpNode = diagramContentNodes(versioned.documents.find(d => d.id === docA).proposed.document.scene.contents.overview.content).find(node => node.label === 'Canvas A updated');
  assert.ok(jumpNode);
  await changes.update({ changeSessionId: id, expectedVersion: versioned.version, requestId: 'navigation', diffTree: {
    expectedRevisionId: proposal.diffTree.revisionId, mappings: tree.mappings.map(m => ({ ...m, diagramTargets: [{ representationId: docA, displayNodeId: 'grid:overview', contentNodeId: jumpNode.id }] }))
  } });
  const fixtureVersion = (await changes.get(id)).version;
  // Rendering must use the session snapshot, even when files no longer match it.
  await writeFile(path.join(root, 'logic.ts'), 'LIVE WORKTREE CONTENT MUST NOT APPEAR');
  const port = await new Promise(resolve => { const s = createServer(); s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => resolve(p)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', '--http', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'], {
    env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: store.storeRoot, NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'ignore', 'pipe'] });
  let logs = ''; server.stderr.on('data', d => logs += d);
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 }).catch(e => { throw Error(`${e}\n${logs}`); });
  await withHeadlessBrowser({ url: `${url}/mapping`, width: 1600, height: 1000, chromePath: process.env.CHROME_PATH, arguments: ['--disable-gpu'] }, async ({ cdp }) => {
    const send = cdp.send.bind(cdp);
    cdp.send = async (method, params) => { let timer; try { return await Promise.race([send(method, params), new Promise((_, reject) => { timer = setTimeout(() => reject(Error(`CDP timeout: ${method}`)), 20000); })]); } finally { clearTimeout(timer); } };
    await cdp.send('Page.enable'); cdp.on('Page.javascriptDialogOpening', () => void cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    const errors = []; await cdp.send('Runtime.enable'); cdp.on('Runtime.exceptionThrown', e => errors.push(e.exceptionDetails.text));
    const read = expression => evaluate(cdp, expression);
    const assertWorkspaceGeometry = async () => {
      const shifted = await read(`['html','body','#root','.mapping-poc-shell','.mapping-viewport','.window-panel','.window-panel-primary','.window-panel-secondary'].flatMap(selector=>[...document.querySelectorAll(selector)].filter(e=>e.scrollLeft||e.scrollTop).map(e=>({selector,left:e.scrollLeft,top:e.scrollTop})))`);
      assert.deepEqual(shifted, [], 'Only the tree and hunk scroll containers may scroll');
    };
    const until = expression => waitFor(() => read(expression)).catch(async error => { if (process.env.DIFF_TREE_SCREENSHOT) await captureScreenshot(cdp, { output: process.env.DIFF_TREE_SCREENSHOT }); throw Error(`${error}: ${expression}\n${await read('document.body.innerText')}`); });
    const assertJumpCentered = async () => {
      await until(`(()=>{
        const preview=document.querySelector('.mapping-viewport > .change-session-preview');
        const target=preview?.querySelector('[data-jump-focus]'); if(!target)return false;
        const node=target.getBoundingClientRect(), canvas=preview.querySelector('.mapping-poc-canvas').getBoundingClientRect();
        const explorer=document.querySelector('.mapping-floating-pane').getBoundingClientRect();
        const panel=document.querySelector('.window-panel').getBoundingClientRect();
        const header=preview.querySelector('.change-session-actions').getBoundingClientRect();
        const left=Math.max(canvas.left,explorer.right+12), right=Math.min(canvas.right,panel.left-12);
        const top=Math.max(canvas.top,header.bottom+12);
        return Math.abs(node.left+node.width/2-(left+right)/2)<2 && Math.abs(node.top+node.height/2-(top+canvas.bottom)/2)<2
          && node.left>=left && node.right<=right && node.top>=top && node.bottom<=canvas.bottom;
      })()`);
    };
    const point = async (selector, text) => {
      let p, previous; await waitFor(async () => {
        p = await read(`(async()=>{const e=[...document.querySelectorAll(${JSON.stringify(selector)})].find(e=>!e.disabled&&e.getClientRects().length&&(!${JSON.stringify(text ?? '')}||e.textContent.trim()===${JSON.stringify(text ?? '')}));if(!e)return null;e.scrollIntoView({block:'nearest'});await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const r=e.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2};})()`); const stable = p && previous && p.x === previous.x && p.y === previous.y; previous = p; return !!stable;
      }); return p;
    };
    const click = async (selector, text) => { const p = await point(selector, text); await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...p, button: 'left', buttons: 1, clickCount: 1 }); await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...p, button: 'left', buttons: 0, clickCount: 1 }); };
    const key = async key => { const params = { key, code: key, windowsVirtualKeyCode: { Home: 36, End: 35, Enter: 13, ArrowDown: 40, ArrowUp: 38, ArrowLeft: 37, ArrowRight: 39 }[key] }; await cdp.send('Input.dispatchKeyEvent', { type: 'rawKeyDown', ...params }); await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', ...params }); };
    const layout = async mode => { await click('[aria-label="Window panel layout"]'); await key('Home'); for (let i = 0; i < ['full-single', 'full-split', 'split-single'].indexOf(mode); i++) await key('ArrowDown'); await key('Enter'); await waitForSelector(cdp, `.window-panel-${mode}`); };
    const open = async doc => { await click(`details:has(> [data-change-session-summary="${id}"]) [data-open-difftree-document="${doc}"]`); await until(`!!document.querySelector('[data-window-panel-canvas="${doc}"]')`); };
    const node = name => `[role=treeitem][aria-label="${name}"]`;
    const topHunk = () => read(`(()=>{const e=document.querySelector('.diff-hunks-scroll'), r=e.getBoundingClientRect();return document.elementFromPoint(r.left + 100, r.top + 10)?.closest('[data-hunk-id]')?.dataset.hunkId})()`);
    const hunkPaths = () => read('[...document.querySelectorAll(".diff-hunk-header strong")].map(e=>e.textContent)');
    await waitForSelector(cdp, '[data-project-diagram]');
    assert.equal(await read('document.querySelectorAll("[data-open-difftree]").length'), 0);
    await click('[role=tab]', 'Changes'); await click(`[data-change-session-summary="${id}"]`); await open(docA);
    await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    const find = async (global = false) => {
      await cdp.send('Input.dispatchKeyEvent', { type: 'rawKeyDown', key: 'b', code: 'KeyB', windowsVirtualKeyCode: 66, modifiers: 2 });
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'b', code: 'KeyB', windowsVirtualKeyCode: 66 });
      await cdp.send('Input.dispatchKeyEvent', { type: 'rawKeyDown', key: 'f', code: 'KeyF', windowsVirtualKeyCode: 70, modifiers: global ? 8 : 0 });
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'f', code: 'KeyF', windowsVirtualKeyCode: 70 });
      await until('document.activeElement?.getAttribute("aria-label") === "Search diagram text"');
    };
    await find();
    await cdp.send('Input.insertText', { text: 'updated' });
    await until('document.querySelector(".diagram-search-panel [role=status]")?.textContent === "1 matching line"');
    assert.ok(await read(`(()=>{const input=document.querySelector('[aria-label="Search diagram text"]'),r=input.getBoundingClientRect();return document.elementFromPoint(r.left+r.width/2,r.top+r.height/2)===input})()`), 'Search must be usable above the expanded DiffTree');
    assert.equal(await read('document.querySelector("[data-search-result-canvas]").dataset.searchResultCanvas'), `proposal:${id}:${docA}`);
    await key('Enter');
    await until('!!document.querySelector(".window-panel-minimized") && !!document.querySelector(".mapping-viewport > .change-session-preview .diagram-search-highlight.is-current")');
    await until(`(()=>{const h=document.querySelector('.mapping-viewport > .change-session-preview .diagram-search-highlight.is-current').getBoundingClientRect(), p=document.querySelector('.window-panel').getBoundingClientRect(), e=document.querySelector('.mapping-floating-pane').getBoundingClientRect();return h.left>e.right && h.right<p.left})()`);
    await find(true);
    await until('document.querySelector(".diagram-search-panel [role=status]")?.textContent === "0 matching lines"');
    await find();
    await until('document.querySelector(".diagram-search-panel [role=status]")?.textContent === "1 matching line"');
    await cdp.send('Input.dispatchKeyEvent', { type: 'rawKeyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
    await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
    await until('!document.querySelector(".diagram-search-panel")?.checkVisibility()');
    await click('.window-panel [aria-label="Search diagrams"]');
    await until('document.activeElement?.getAttribute("aria-label") === "Search diagram text"');
    await click('[aria-label="Close diagram search"]');
    await until('!document.querySelector(".diagram-search-panel")?.checkVisibility()');
    await click('[aria-label="Restore split view"]');
    await until('!document.querySelector(".window-panel-minimized")');
    console.log('Verified Ctrl+B, F over DiffTree, proposal-only results, search focus reveal and project-scope isolation');
    const pinchPoint = await read(`(()=>{const r=document.querySelector('.diff-tree-scroll').getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);
    await cdp.send('Input.synthesizePinchGesture', { ...pinchPoint, scaleFactor: 1.15, relativeSpeed: 800, gestureSourceType: 'mouse' });
    await read('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))');
    assert.deepEqual(await read('({scale:visualViewport.scale,left:visualViewport.offsetLeft,top:visualViewport.offsetTop})'), {scale:1,left:0,top:0}, 'Pinching the DiffTree zoomed or shifted the entire page');
    await assertWorkspaceGeometry();
    assert.equal(await read('document.querySelector(".window-panel").classList.contains("window-panel-full-split")'), true);
    assert.ok(await read('document.querySelector(".diff-hunk-metadata").textContent.includes("Binary file changed")'));
    assert.ok(await read('document.querySelector(".window-panel").getBoundingClientRect().left > document.querySelector(".mapping-floating-pane").getBoundingClientRect().right'));
    assert.equal(await read('document.querySelectorAll(".diff-coverage").length > 0'), true);
    assert.equal(await read('[...document.querySelectorAll(".window-panel button")].some(e=>e.textContent === "Load more hunks")'), false);
    await click('.window-panel button', 'Collapse to outline');
    await until(`!document.querySelector('${node('Detail')}')`);
    assert.equal(await read(`document.querySelector('${node('Logic')}').getAttribute('aria-expanded')`), 'false');
    await click('.ascii-line:has([aria-label="Logic"]) .diagram-jump');
    await until('!!document.querySelector(".window-panel-minimized") && !!document.querySelector(".change-session-preview .is-change-target")');
    await assertJumpCentered();
    assert.equal(await read(`document.querySelector('${node('Logic')}').getAttribute('aria-selected')`), 'true', 'Diagram jump must select its tree node');
    assert.equal(await read('document.querySelectorAll("[data-scroll-tracked=true]").length'), 0, 'Minimized tree must hide the yellow marker');
    const canvasNode = '.mapping-viewport > .change-session-preview .diagram-content-node';
    const cameraBeforeClick = await read('document.querySelector(".mapping-viewport > .change-session-preview .diagram-canvas__surface").style.transform');
    await click(canvasNode);
    assert.equal(await read('document.querySelectorAll(".diagram-mapping-choices").length'), 0, 'Canvas clicks do not open DiffTree jump menus');
    assert.equal(await read('document.querySelector(".mapping-viewport > .change-session-preview .diagram-canvas__surface").style.transform'), cameraBeforeClick);
    await click(node('Logic'));
    await until('document.querySelectorAll(".diff-hunk").length === 2');
    assert.deepEqual(await hunkPaths(), ['logic.ts', 'logic.ts'], 'Minimized node activation must filter to its mapped hunks');
    assert.ok(await read('document.querySelector(".diff-pane-toolbar").textContent.includes("2 mapped hunks")'));
    await click('.window-panel [role=tab]', 'Change tree');
    await click(node('Unmapped'));
    await until('document.querySelector(".diff-hunks-scroll")?.textContent.includes("No hunks mapped to this node.")');
    assert.deepEqual(await hunkPaths(), []);
    await click('.window-panel button', 'All changes');
    await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await click('.window-panel [role=tab]', 'Change tree');
    await click(node('Review'));
    await until('document.querySelectorAll(".diff-hunk").length === 3');
    assert.deepEqual((await hunkPaths()).sort(), ['logic.ts', 'logic.ts', 'removed.txt'], 'Grouping nodes must include descendant mappings');
    await click('[aria-label="Restore split view"]');
    await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await click('[aria-label="Minimize to focused pane"]');
    await until('document.querySelectorAll(".diff-hunk").length === 3');
    console.log('Verified minimized node filtering, empty mappings, descendant mappings and expanded full-list restoration');
    await click('[aria-label="Restore split view"]');
    await click(node('Logic'));
    await waitFor(async () => await topHunk() === discovered.hunks.find(h => h.path === 'logic.ts').id).catch(async error => {
      console.log('Hunk scroll state', await read(`(()=>{const c=document.querySelector('.diff-hunks-scroll'),r=c.getBoundingClientRect();return {scroll:c.scrollTop,top:document.elementFromPoint(r.left+100,r.top+10)?.outerHTML,logic:[...c.querySelectorAll('[data-hunk-id]')].filter(e=>e.textContent.includes('logic.ts')).map(e=>({id:e.dataset.hunkId,top:e.getBoundingClientRect().top-r.top,height:e.getBoundingClientRect().height})),state:JSON.parse(sessionStorage.getItem('diff-tree:${id}'))}})()`));
      if(process.env.DIFF_TREE_SCREENSHOT) await captureScreenshot(cdp,{output:process.env.DIFF_TREE_SCREENSHOT});
      throw error;
    });
    assert.equal(await read(`!!document.querySelector('${node('Detail')}')`), false, 'Hunk tracking reopened the outline');
    assert.equal((await hunkPaths()).length, discovered.total);
    if (process.env.DIFF_TREE_SCREENSHOT) await captureScreenshot(cdp, { output: process.env.DIFF_TREE_SCREENSHOT.replace('.png', '-outline.png') });
    await assertWorkspaceGeometry();
    await click('.window-panel button', 'Expand all');
    await waitForSelector(cdp, node('Detail'));
    await click('.window-panel button', 'All changes');
    const scrollPoint = await read(`(()=>{const r=document.querySelector('.diff-hunks-scroll').getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...scrollPoint, deltaX: 0, deltaY: -100000 });
    await until('document.querySelector(".diff-hunks-scroll").scrollTop === 0');
    const scrollbarPoint = await read(`(()=>{const r=document.querySelector('.diff-hunks-scroll').getBoundingClientRect();return{x:r.right-7,y:r.bottom-30}})()`);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...scrollbarPoint, button: 'left', buttons: 1, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...scrollbarPoint, button: 'left', buttons: 0, clickCount: 1 });
    await until('document.querySelector(".diff-hunks-scroll").scrollTop > 0');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...scrollPoint, deltaX: 0, deltaY: 500 });
    await until('document.querySelector(".diff-hunks-scroll").scrollTop > 300');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...scrollPoint, deltaX: 0, deltaY: 100000 });
    await until(`document.querySelector('[data-scroll-tracked="true"]')?.getAttribute('aria-label') === 'Removed file'`);
    assert.equal(await read(`document.querySelector('[role=treeitem][aria-selected="true"]')`), null);
    assert.equal(await read('document.querySelector("[data-pane=hunks]").dataset.focused'), 'true');
    await click(node('Detail')); await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await click('.window-panel button', 'All changes');
    await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total} && document.querySelector('.diff-hunks-scroll').scrollTop === 0`);
    console.log('Verified complete prefetch, scroll restoration and explorer clearance');
    await click(node('Detail')); await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await until('document.querySelector("[data-pane=tree]").dataset.focused === "true"');
    await click(`[data-hunk-id="${discovered.hunks.find(h => h.path === 'logic.ts').id}"] button`, 'Copy patch');
    await until('document.querySelector("[data-pane=hunks]").dataset.focused === "true"');
    const canvasState = () => read(`(()=>{const e=document.querySelector('.mapping-viewport > .change-session-preview .diagram-canvas__surface'); const r=e.closest('.mapping-poc-canvas').getBoundingClientRect();return {transform:e.style.transform,width:r.width,height:r.height}})()`);
    const cameraBefore = await canvasState();
    await click('[aria-label="Minimize to focused pane"]');
    await until('!!document.querySelector(".window-panel-minimized") && !document.querySelector(".diff-tree-scroll")');
    assert.ok(await read('Math.abs(document.querySelector(".window-panel").getBoundingClientRect().width / document.querySelector(".mapping-viewport").getBoundingClientRect().width - .4) < .01'));
    assert.deepEqual(await canvasState(), cameraBefore, 'Minimizing changed the canvas camera');
    assert.equal((await hunkPaths()).length, discovered.total);
    const compactScrollPoint = await read(`(()=>{const r=document.querySelector('.diff-hunks-scroll').getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...compactScrollPoint, deltaX: 0, deltaY: 100000 });
    await until(`(()=>{const e=document.querySelector('.diff-hunks-scroll');return e.scrollTop + e.clientHeight >= e.scrollHeight - 2})()`);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...compactScrollPoint, deltaX: 0, deltaY: -100000 });
    await until('document.querySelector(".diff-hunks-scroll").scrollTop === 0');
    const edge = await point('[aria-label="Resize window width"]');
    const initialWidth = await read('document.querySelector(".window-panel").getBoundingClientRect().width');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...edge, button: 'left', buttons: 1, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: edge.x - 120, y: edge.y, button: 'left', buttons: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: edge.x - 120, y: edge.y, button: 'left', buttons: 0, clickCount: 1 });
    await until(`document.querySelector('.window-panel').getBoundingClientRect().width > ${initialWidth + 100}`);
    const resizedWidth = await read('document.querySelector(".window-panel").getBoundingClientRect().width');
    assert.ok(resizedWidth > initialWidth + 100);
    const bottom = await point('[aria-label="Resize window height"]');
    const initialHeight = await read('document.querySelector(".window-panel").getBoundingClientRect().height');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...bottom, button: 'left', buttons: 1, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: bottom.x, y: bottom.y - 100, button: 'left', buttons: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: bottom.x, y: bottom.y - 100, button: 'left', buttons: 0, clickCount: 1 });
    await until(`document.querySelector('.window-panel').getBoundingClientRect().height < ${initialHeight - 80}`);
    assert.deepEqual(await canvasState(), cameraBefore, 'Resizing changed the canvas camera');
    await click('[aria-label="Restore split view"]');
    assert.deepEqual(await canvasState(), cameraBefore, 'Restoring changed the canvas camera');
    await click('[aria-label="Minimize to focused pane"]');
    assert.equal(await read('document.querySelector(".window-panel").getBoundingClientRect().width'), resizedWidth);
    await click('[aria-label="Restore split view"]');
    console.log('Verified minimized edge resizing, saved width and unchanged canvas camera');
    await click(`[data-hunk-id="${discovered.hunks.find(h => h.path === 'logic.ts').id}"] button`, 'Diagram ↗');
    await until('!!document.querySelector(".window-panel-minimized") && !!document.querySelector(".change-session-preview .is-change-target")');
